import java.util.Scanner;

public class Main {
    static int n, m, mod;
    static int[] g = new int[505], sg = new int[505];
    static int[][] f = new int[505][505], sf = new int[505][505];
    static int[][] C = new int[505][505];

    static int add(int ta, int tb) {
        return ta + tb >= mod ? ta + tb - mod : ta + tb;
    }

    static int sub(int ta, int tb) {
        return ta < tb ? ta - tb + mod : ta - tb;
    }

    static void make_C() {
        C[0][0] = 1;
        for (int i = 1; i <= n; i++) {
            C[i][0] = 1;
            for (int j = 1; j <= i; j++) {
                C[i][j] = add(C[i - 1][j], C[i - 1][j - 1]);
            }
        }
    }

    static int S1(int tn) {
        long res = (long) tn * (tn + 1) / 2 % mod;
        return (int) res;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        m = sc.nextInt();
        mod = sc.nextInt();
        sc.close();

        make_C();

        g[0] = 1;
        for (int i = 1; i <= m; i++) {
            for (int j = 1; j <= i; j++) {
                long tmp = (long) g[j - 1] * g[i - j] % mod * C[i - 1][j - 1] % mod;
                g[i] = add(g[i], (int) (tmp * (i + 1) % mod));
                sg[i] = add(sg[i], (int) (tmp * (long) sg[j - 1] % mod * g[i - j] % mod * C[i - 1][j - 1] % mod * (i + 1) % mod));
                sg[i] = add(sg[i], (int) (tmp * (long) sg[i - j] % mod * g[j - 1] % mod * C[i - 1][j - 1] % mod * (i + 1) % mod));
                sg[i] = add(sg[i], (int) (tmp * (long) (S1(i - j) + S1(j - 1)) % mod));
            }
        }

        for (int i = 0; i <= n; i++) {
            f[i][0] = 1;
        }

        for (int i = 1; i <= n; i++) {
            if (i <= m) {
                f[i][i] = g[i];
                sf[i][i] = sg[i];
            }
            for (int j = 1; j <= Math.min(i - 1, m); j++) {
                for (int t = i; t >= 1; t--) {
                    if (i - t > j) break;
                    long tmp = (long) g[i - t] * C[j][i - t] % mod;
                    f[i][j] = add(f[i][j], (int) (f[t - 1][j - i + t] * tmp % mod));
                    sf[i][j] = add(sf[i][j], (int) (sf[t - 1][j - i + t] * tmp % mod));
                    sf[i][j] = add(sf[i][j], (int) (f[t - 1][j - i + t] * (long) sg[i - t] % mod * C[j][i - t] % mod));
                }
            }
        }

        System.out.println(sf[n][m]);
    }
}
